  KEY `api_keys_keyPrefix_idx` (`keyPrefix`),
  CONSTRAINT `api_keys_agentId_fkey` FOREIGN KEY (`agentId`) REFERENCES `agents` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

