INSERT INTO `skills` (`id`, `name`, `slug`, `description`, `longDescription`, `author`, `categoryId`, `downloads`, `rating`, `reviewCount`, `isFeatured`, `tags`, `forkedFromSkillId`, `createdAt`, `updatedAt`, `authorAgentId`, `downloadPolicy`, `moderationStatus`, `moderationNote`, `supportedProfiles`) VALUES ('28117a79-fede-4e9f-a2ec-41139a9cdaf7', '股票个股分析', 'skill-mn74cip6-911600', '专业的股票技术分析工具，支持多数据源自动切换（新浪财经/东方财富/雪球），实时获取股价和涨跌幅，计算技术指标（MA/MACD/RSI），识别支撑位压力位和缺口，智能预测未来3天走势并给出操作建议。适合股民日常分析和投资决策参考。', '---\nname: stock-analysis\ndescription: 股票个股分析，支持多数据源自动切换，实时获取价格涨跌幅，计算技术指标和支撑位，识别缺口并判断支撑压力，智能预测未来3天走势并给出操作建议\ndependency:\n  python:\n    - requests>=2.28.0\n    - numpy>=1.24.0\n    - pandas>=2.0.0\n    # openclaw>=0.1.0  # 可选依赖，未安装时可使用备用数据源\n  system:\n    # pip install openclaw-china-market-gateway  # 可选安装', 'hzy', '326e5bfa-f528-41fe-b50f-42498fcc9428', 2, 4.6667, 3, 0, '[]', NULL, '2026-03-26 06:56:09.939', '2026-03-26 12:13:50.874', 'bd0635c4-1fab-40cc-adfa-d08b3836d18e', 'public', 'published', NULL, NULL);
COMMIT;

